const items = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) throw new Error('No se recibió ninguna foto.');
  const key = binaryKeys[0];
  const binary = item.binary[key];
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const base64 = buffer.toString('base64');
  let mediaType = binary.mimeType || 'image/jpeg';
  if (!['image/jpeg','image/png','image/webp','image/gif'].includes(mediaType)) mediaType = 'image/jpeg';
  const sel = (item.json['Qué generar'] || 'Ambos').toLowerCase();
  const mode = sel.includes('stories') ? 'stories' : sel.includes('tiktok') ? 'tiktok' : 'both';
  items.push({ json: { base64, mediaType, mode, filename: binary.fileName || 'foto' } });
}
return items;

const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const text = item.json.content?.[0]?.text || '';
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}') + 1;
  let plan;
  try { plan = JSON.parse(text.slice(start, end)); }
  catch (e) { plan = { error: 'No se pudo parsear', raw: text }; }
  const prep = $('Preparar Imagen').all()[i] || $('Preparar Imagen').first();
  plan._base64 = prep?.json?.base64 || '';
  plan._mediaType = prep?.json?.mediaType || 'image/jpeg';
  out.push({ json: plan });
}
return out;

const p = $input.first().json;
if (p.error) { return [{ json: { html: '<div style="color:#ff6b6b;padding:20px;font-family:sans-serif">Error: ' + p.error + '</div>' } }]; }
const imgSrc = p._base64 ? ('data:' + (p._mediaType || 'image/jpeg') + ';base64,' + p._base64) : '';
function esc(t){ return (t||'').toString().replace(/</g,'&lt;'); }
const W = 175, H = 311;
const photoBg = imgSrc ? ('background:url(' + imgSrc + ') center/cover no-repeat;') : 'background:linear-gradient(160deg,#222,#0d0d0d);';
function frame(num, inner){
  const logo = '<div style="position:absolute;top:10px;right:11px;font-family:Georgia,serif;font-size:13px;color:#fff;letter-spacing:2px;z-index:5;text-shadow:0 1px 4px rgba(0,0,0,.6)">kÖr</div>';
  const badge = '<div style="position:absolute;top:8px;left:9px;width:22px;height:22px;border-radius:50%;background:#e8175d;color:#fff;font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center;z-index:6">' + num + '</div>';
  const h = '<div style="position:absolute;bottom:8px;left:0;right:0;text-align:center;color:rgba(255,255,255,.6);font-size:8px;letter-spacing:1px;z-index:5">@_korsv</div>';
  return '<div style="position:relative;width:' + W + 'px;height:' + H + 'px;border-radius:16px;overflow:hidden;flex-shrink:0;' + photoBg + '">' + inner + badge + logo + h + '</div>';
}
function prev(s, i){
  const t = (s.template||'MOTIVATION').toUpperCase();
  const head=esc(s.headline), txt=esc(s.overlay_text), prod=esc(s.product), price=esc(s.price), cta=esc(s.cta)||'Ver más';
  const n = i+1;
  if(t==='DROP') return frame(n, '<div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.8),rgba(0,0,0,.1) 55%)"></div><div style="position:absolute;top:40px;left:0;right:0;text-align:center"><div style="display:inline-block;background:#e8175d;color:#fff;font-size:10px;font-weight:800;letter-spacing:3px;padding:5px 13px;transform:rotate(-3deg)">' + (head||'NUEVO DROP') + '</div></div><div style="position:absolute;bottom:40px;left:13px;right:13px"><div style="color:#fff;font-size:16px;font-weight:800;line-height:1.1;text-shadow:0 2px 8px #000">' + (prod||txt) + '</div>' + (price?'<div style="color:#e8175d;font-size:19px;font-weight:900;margin-top:4px;text-shadow:0 2px 6px #000">' + price + '</div>':'') + '</div>');
  if(t==='SHOP') return frame(n, '<div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.85),transparent 60%)"></div><div style="position:absolute;bottom:48px;left:13px;right:13px"><div style="color:#fff;font-size:14px;font-weight:700;text-shadow:0 2px 6px #000">' + (prod||txt) + '</div>' + (price?'<div style="color:#fff;font-size:17px;font-weight:900;margin:4px 0">' + price + '</div>':'') + '<div style="display:inline-block;background:#fff;color:#0a0a0a;font-size:9px;font-weight:800;letter-spacing:1px;padding:6px 14px;border-radius:20px;margin-top:5px">🛍 ' + cta + '</div></div>');
  if(t==='COUNTDOWN') return frame(n, '<div style="position:absolute;inset:0;background:rgba(0,0,0,.55)"></div><div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:86%;text-align:center"><div style="color:rgba(255,255,255,.85);font-size:9px;letter-spacing:3px;margin-bottom:9px">PRÓXIMAMENTE</div><div style="background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.3);border-radius:14px;padding:13px 9px"><div style="color:#fff;font-size:14px;font-weight:800;line-height:1.2">' + (txt||head) + '</div><div style="color:#e8175d;font-size:8px;font-weight:700;letter-spacing:2px;margin-top:6px">⏳ ACTIVA EL RECORDATORIO</div></div></div>');
  if(t==='RESTOCK') return frame(n, '<div style="position:absolute;inset:0;background:linear-gradient(135deg,rgba(0,0,0,.4),rgba(0,0,0,.7))"></div><div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-8deg);width:90%;text-align:center"><div style="border:3px solid #fff;border-radius:8px;padding:9px 6px;background:rgba(232,23,93,.25)"><div style="color:#fff;font-size:18px;font-weight:900;letter-spacing:1px;line-height:1">DE VUELTA<br>EN STOCK</div></div><div style="color:#fff;font-size:10px;font-weight:600;margin-top:9px;text-shadow:0 1px 4px #000">' + (prod||txt) + '</div></div>');
  if(t==='UGC'){ const user = esc(s.username)||'@cliente'; return frame(n, '<div style="position:absolute;inset:0;background:rgba(0,0,0,.35)"></div><div style="position:absolute;top:36px;left:11px;display:flex;align-items:center;gap:6px;background:rgba(0,0,0,.4);padding:4px 10px 4px 4px;border-radius:20px"><div style="width:20px;height:20px;border-radius:50%;background:linear-gradient(45deg,#e8175d,#8b1fd4)"></div><div style="color:#fff;font-size:10px;font-weight:600">' + user + '</div></div><div style="position:absolute;bottom:48px;left:11px;right:11px;background:rgba(0,0,0,.45);border-radius:12px;padding:8px 11px"><div style="color:#fff;font-size:11px;font-weight:600">' + (txt||'Repost de la comunidad 🖤') + '</div><div style="color:rgba(255,255,255,.7);font-size:8px;margin-top:2px">Etiquétanos con tu fit kÖr</div></div>'); }
  if(t==='POLL'){ const a = esc(s.poll_a)||'Sí 🔥', b = esc(s.poll_b)||'Obvio 💪'; return frame(n, '<div style="position:absolute;inset:0;background:rgba(0,0,0,.4)"></div><div style="position:absolute;top:46%;left:50%;transform:translate(-50%,-50%);width:86%;text-align:center"><div style="color:#fff;font-size:13px;font-weight:700;text-shadow:0 2px 6px #000;margin-bottom:11px">' + (txt||head) + '</div><div style="display:flex;border-radius:24px;overflow:hidden"><div style="flex:1;background:rgba(255,255,255,.92);color:#0a0a0a;font-size:10px;font-weight:700;padding:8px 4px">' + a + '</div><div style="flex:1;background:#e8175d;color:#fff;font-size:10px;font-weight:700;padding:8px 4px">' + b + '</div></div></div>'); }
  return frame(n, '<div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.6),rgba(0,0,0,.3))"></div><div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:84%;text-align:center"><div style="color:#fff;font-size:19px;font-weight:800;line-height:1.15;text-shadow:0 2px 10px #000">' + (txt||head) + '</div></div>');
}
let html = '<div style="font-family:Helvetica,Arial,sans-serif">';
if (p.stories && p.stories.length) {
  html += '<div style="display:flex;gap:12px;overflow-x:auto;padding:4px 0 10px">' + p.stories.map((s,i)=>prev(s,i)).join('') + '</div>';
  html += '<p style="font-size:13px;color:#555;margin:8px 0 0">Elige abajo cuál historia enviar a tu Telegram (1, 2 o 3).</p>';
}
if (p.tiktok && p.tiktok.format) {
  html += '<div style="margin-top:16px;font-size:13px;color:#333"><strong>🎬 TikTok [' + esc(p.tiktok.format) + ']</strong> — ' + esc(p.tiktok.duration||'') + '<br>' + (p.tiktok.script||[]).map(s=>'<span style="color:#e8175d">'+esc(s.time||'')+'</span> '+esc(s.action||'')).join('<br>') + '</div>';
}
html += '</div>';
return [{ json: { html } }];

const plan = $('Parsear Resultado').first().json;
const choiceRaw = ($json['¿Cuál enviar a Telegram?'] || 'Historia 1') + '';
const num = parseInt(choiceRaw.replace(/[^0-9]/g,'') || '1', 10);
const idx = Math.max(0, num - 1);
const s = (plan.stories||[])[idx] || (plan.stories||[])[0] || {};
const imgSrc = plan._base64 ? ('data:' + (plan._mediaType||'image/jpeg') + ';base64,' + plan._base64) : '';
function e(t){ return (t||'').toString().replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const T = (s.template||'MOTIVATION').toUpperCase();
const txt=e(s.overlay_text), prod=e(s.product), price=e(s.price), head=e(s.headline);
const cta = e(s.cta)||'Ver colección';
// Fuentes Google cargadas en el HTML
const fonts = '<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Inter:wght@300;400;500&display=swap" rel="stylesheet">';
const serif = 'font-family:Cormorant Garamond,Georgia,serif';
const sans = 'font-family:Inter,Helvetica,sans-serif';
const bg = imgSrc ? 'background:url(' + imgSrc + ') center/cover no-repeat' : 'background:#0a0a0a';
// Logo kÖr — serif elegante arriba izquierda
const logo = '<div style="position:absolute;top:72px;left:72px;' + serif + ';font-size:72px;font-weight:300;color:#fff;letter-spacing:12px;z-index:10">kÖr</div>';
// Handle abajo centrado
const handle = '<div style="position:absolute;bottom:72px;left:0;right:0;text-align:center;' + sans + ';font-size:32px;font-weight:300;color:rgba(255,255,255,.5);letter-spacing:6px;z-index:10">@_korsv</div>';
// Línea fina decorativa bajo el logo
const lineTop = '<div style="position:absolute;top:168px;left:72px;width:120px;height:1px;background:rgba(255,255,255,.35);z-index:10"></div>';
let inner = '';

if(T==='DROP'){
// Editorial — foto full, franja negra abajo con nombre y precio en serif
inner = '<div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.92) 0%,rgba(0,0,0,.0) 55%)"></div>';
inner += '<div style="position:absolute;bottom:180px;left:72px;right:72px">';
inner += '<div style="' + sans + ';font-size:24px;font-weight:300;color:rgba(255,255,255,.6);letter-spacing:8px;text-transform:uppercase;margin-bottom:20px">nueva llegada</div>';
inner += '<div style="' + serif + ';font-size:110px;font-weight:400;color:#fff;line-height:1;letter-spacing:2px">' + (prod||txt) + '</div>';
if(price) inner += '<div style="' + serif + ';font-size:80px;font-weight:300;color:#fff;margin-top:16px;opacity:.9">' + price + '</div>';
inner += '<div style="margin-top:40px;display:inline-block;border:1px solid rgba(255,255,255,.4);' + sans + ';font-size:28px;font-weight:300;color:#fff;letter-spacing:6px;text-transform:uppercase;padding:20px 48px">' + cta + '</div>';
inner += '</div>';
}
else if(T==='SHOP'){
// Foto + caja blanca semitransparente centrada con producto y precio
inner = '<div style="position:absolute;inset:0;background:rgba(0,0,0,.25)"></div>';
inner += '<div style="position:absolute;bottom:200px;left:60px;right:60px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);backdrop-filter:blur(12px);padding:60px 56px">';
inner += '<div style="' + sans + ';font-size:22px;font-weight:300;letter-spacing:8px;text-transform:uppercase;color:rgba(255,255,255,.55);margin-bottom:22px">disponible</div>';
inner += '<div style="' + serif + ';font-size:92px;font-weight:400;color:#fff;line-height:1.05;margin-bottom:18px">' + (prod||txt) + '</div>';
if(price) inner += '<div style="' + serif + ';font-size:72px;font-weight:300;color:#fff;margin-bottom:40px">' + price + '</div>';
inner += '<div style="' + sans + ';font-size:26px;font-weight:400;color:#fff;letter-spacing:4px;text-transform:uppercase;opacity:.7">' + cta + ' →</div>';
inner += '</div>';
}
else if(T==='COUNTDOWN'){
// Oscuro total, texto serif centrado con detalle de líneas
inner = '<div style="position:absolute;inset:0;background:rgba(0,0,0,.7)"></div>';
inner += '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:78%;text-align:center">';
inner += '<div style="width:60px;height:1px;background:rgba(255,255,255,.4);margin:0 auto 60px"></div>';
inner += '<div style="' + sans + ';font-size:22px;font-weight:300;color:rgba(255,255,255,.5);letter-spacing:10px;text-transform:uppercase;margin-bottom:36px">próximamente</div>';
inner += '<div style="' + serif + ';font-size:100px;font-weight:300;color:#fff;line-height:1.1;font-style:italic">' + (txt||head) + '</div>';
inner += '<div style="width:60px;height:1px;background:rgba(255,255,255,.4);margin:60px auto 0"></div>';
inner += '</div>';
}
else if(T==='RESTOCK'){
// Foto con banda diagonal y texto elegante
inner = '<div style="position:absolute;inset:0;background:rgba(0,0,0,.45)"></div>';
inner += '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:86%;text-align:center">';
inner += '<div style="border-top:1px solid rgba(255,255,255,.5);border-bottom:1px solid rgba(255,255,255,.5);padding:44px 0;margin-bottom:32px">';
inner += '<div style="' + sans + ';font-size:22px;font-weight:300;color:rgba(255,255,255,.6);letter-spacing:10px;text-transform:uppercase;margin-bottom:20px">de vuelta</div>';
inner += '<div style="' + serif + ';font-size:90px;font-weight:400;color:#fff;line-height:1">' + (prod||txt) + '</div>';
inner += '</div>';
inner += '<div style="' + sans + ';font-size:24px;font-weight:300;color:rgba(255,255,255,.55);letter-spacing:6px;text-transform:uppercase">solo por tiempo limitado</div>';
inner += '</div>';
}
else if(T==='UGC'){
const user = e(s.username)||'@cliente';
inner = '<div style="position:absolute;inset:0;background:rgba(0,0,0,.3)"></div>';
// Header estilo repost
inner += '<div style="position:absolute;top:160px;left:0;right:0;' + sans + ';font-size:24px;font-weight:300;color:rgba(255,255,255,.6);letter-spacing:4px;text-align:center">nuestra comunidad</div>';
inner += '<div style="position:absolute;bottom:200px;left:64px;right:64px">';
inner += '<div style="' + serif + ';font-size:80px;font-weight:400;color:#fff;font-style:italic;line-height:1.2;margin-bottom:28px">' + (txt||'La ropa que te hace rendir') + '</div>';
inner += '<div style="' + sans + ';font-size:30px;font-weight:300;color:rgba(255,255,255,.6);letter-spacing:3px">' + user + '</div>';
inner += '</div>';
}
else if(T==='POLL'){
const a = e(s.poll_a)||'Sí', b = e(s.poll_b)||'No';
inner = '<div style="position:absolute;inset:0;background:rgba(0,0,0,.5)"></div>';
inner += '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:82%;text-align:center">';
inner += '<div style="' + serif + ';font-size:88px;font-weight:300;color:#fff;font-style:italic;line-height:1.15;margin-bottom:64px">' + (txt||head) + '</div>';
// Dos opciones estilo kÖr — sin colores agresivos
inner += '<div style="display:flex;gap:24px">';
inner += '<div style="flex:1;border:1px solid rgba(255,255,255,.5);padding:32px 16px;' + sans + ';font-size:38px;font-weight:300;color:#fff;letter-spacing:2px">' + a + '</div>';
inner += '<div style="flex:1;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.5);padding:32px 16px;' + sans + ';font-size:38px;font-weight:300;color:#fff;letter-spacing:2px">' + b + '</div>';
inner += '</div>';
inner += '</div>';
}
else{
// MOTIVATION — la más limpia, cita serif sobre foto oscura
inner = '<div style="position:absolute;inset:0;background:linear-gradient(to bottom,rgba(0,0,0,.2),rgba(0,0,0,.55))"></div>';
inner += '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:80%;text-align:center">';
inner += '<div style="width:48px;height:1px;background:rgba(255,255,255,.5);margin:0 auto 48px"></div>';
inner += '<div style="' + serif + ';font-size:96px;font-weight:300;color:#fff;font-style:italic;line-height:1.2;letter-spacing:1px">' + (txt||head) + '</div>';
inner += '<div style="width:48px;height:1px;background:rgba(255,255,255,.5);margin:48px auto 0"></div>';
inner += '</div>';
}
const html = '<!DOCTYPE html><html><head><meta charset="utf-8">' + fonts + '</head><body style="margin:0"><div style="position:relative;width:1080px;height:1920px;overflow:hidden;' + bg + '">' + inner + logo + lineTop + handle + '</div></body></html>';
const nl = String.fromCharCode(10);
const parts = [];
if(s.caption) parts.push(s.caption);
if(plan.hashtags && plan.hashtags.length) parts.push(plan.hashtags.map(x=>x.charAt(0)==='#'?x:'#'+x).join(' '));
const caption = parts.join(nl+nl);
return [{ json: { html, caption } }];
